// TH15 synthetic training alias, copied from transcribe/th15/touhou-bullets.ecl.
// Only the shape used by this card is included; source type 9 is TH15_KUNAI.
const TH15_KUNAI: int = 496;

// TH15 v1.00b Extra Stage 7 Boss3 (nonspell).
// Source: st07bs.ecl.txt Boss3 335-409, Boss3_at 411-445, public Boss entry state 8-39.
// Rank 4 (Extra). Independent invulnerable training shell in transcribe/th15/validation.md.

const TIME_LIMIT: int = 3724;     // 120 opening buffer + 3600 source window + 4 startup margin
const OPENING_BUFFER: int = 120;

// Source Boss3_at etAngle second arguments: 0.022689281 rad = 1.3 deg,
// 0.027925268 rad = 1.6 deg. Mode 10 (fixed alternating-layer ring) uses
// H(M,q) = (floor(q/2)+1/2)*delta for even M, so H = delta/2 for M=2.
const DELTA_A: int = 237;         // 1.3 deg in BAM
const DELTA_B: int = 291;         // 1.6 deg in BAM
const H_A: int = 118;             // DELTA_A/2
const H_B: int = 145;             // DELTA_B/2

// Source etEx records on every bullet:
//   etEx(0, 0, 2, 1, -999999, -999999.0, -999999.0)  -> ANIM a=1: position -= 4*velocity
//   etEx(0, 0, 2097152, 60, -999999, 6.0, -999999.0) -> VELTIME: 2.0 -> 6.0 over 60 frames,
//                                                        s=-999999 keeps the current angle
// etDist(24) pushes 24px along each bullet angle; ANIM retreat is 4*2 = 8px, net 16px.
// The birth slowdown/no-hit ANIM window is omitted by the shared policy; the retreat
// displacement is kept through sh_dist(16) instead of decomposed per bullet.
xformdef ACCEL_2_6 {
    step_speed(6fx, 60);          // linear 2.0 -> 6.0 over 60 frames, angle unchanged
}

// --- training shell ---------------------------------------------------------
// control owns the phase. pattern waits the 120-frame opening and then creates the
// real source boss. The source timerReset is inside the boss entry, so the 3600-frame
// source window starts around card 121 and ends near 3721; TIME_LIMIT 3724 leaves the
// requested startup margin. BossCard3 is the next-card boundary and is not included.
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 20000, 0, 0, 0, boss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_enemy_flag(ENEMY_KILLALL_EXEMPT, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    // Shell cleanup after the source setInterrupt boundary (BossCard3 is not included).
    // The source boss loops forever inside its own sub, so it does not retire naturally.
    kill_all_enemies(KILL_SILENT);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

// --- source Boss3 entry and attack loop -------------------------------------
async sub boss_main() {
    // Source 337/338: setInvuln(120), lifeSet(20000). HP is the spawn hp; the training
    // shell keeps the real boss invulnerable for the whole segment (no DPS progression).
    set_invuln(65535);
    // Source Boss 31-33: setHurtbox(40,40), setHitbox(48,48), moveLimit(0,128,280,64).
    // Circle branch uses first value*0.5 (TH16/TH18 shared rule): hurt r=20, body r=24.
    set_hurtbox(20fx);
    set_hitbox(24fx);
    // Source 340 etCancel(640), before timerReset: keep the entry clear so a shared
    // world does not carry old bullets into this phase (isolated card has none).
    clear_bullets();
    // Source 353 timerReset is the phase timer boundary (represented by phase_begin).
    // Source 354 killAllAsync: this sub has no child tasks at entry; there is no generic
    // target task-kill API, so there is nothing to cancel.
    // Source 355 enmKillAll: control carries ENEMY_KILLALL_EXEMPT, so this only removes
    // stray non-shell enemies and cannot end the phase early.
    kill_all_enemies(KILL_SILENT);
    // Source 356-357 TIMEOUT==0 branch etCancel(640), after the kills.
    clear_bullets();

    // Source 343-360: etClear/spellEnd/funcSet(0)/laserCancel/playSound, and 366-368
    // zero motion/interpolation. In this isolated card there are no child tasks, lasers,
    // callbacks, sounds or inherited motion; the shell/phase takes them over.
    // Source 369-376 counters, anm/fog/stars/lifeMarker are presentation or scoring.
    // Source 374 setInterrupt(0,3000,3600,"BossCard3") is represented by phase_begin.

    // Source 377: movePosTime(60,4,0,128); 378: wait(120). Spawn is already at the
    // public Boss entry position (0,128), so this move is zero displacement but keeps
    // the 120-frame pre-attack wait and its timing.
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(120);

    // Source 414-422: etSprite(0,9,13) = TH15_KUNAI/color13; etAim(0,10); etCount(25,2);
    // etAngle/etSpeed per wave; etDist(24); the two etEx records above. Mode 10 with
    // M=2 gives both layers speed s0=2.0; the two layers are the +/- mirror of the
    // 25-way ring around %A. sh_ring's layer offset is one signed step, so base %A+H
    // with step -delta reproduces the same two direction rings.
    sh_reset(0);
    sh_sprite(0, TH15_KUNAI, 13);
    sh_ring(0, 1);
    sh_count(0, 25, 2);
    sh_speed(0, 2fx, 0fx);
    sh_dist(0, 16fx);
    sh_xform(0, ACCEL_2_6);

    // Source 386-407: %F0 = 1, -1, 2.718255, -2.718255, each followed by
    // moveRand(60,4,1.9) and wait(60), then the whole sequence repeats.
    loop {
        boss_at(1.0fx);
        move_rand(1.9fx);
        card_wait(60, 1.9fx);
        boss_at(-1.0fx);
        move_rand(1.9fx);
        card_wait(60, 1.9fx);
        boss_at(2.718255fx);
        move_rand(1.9fx);
        card_wait(60, 1.9fx);
        boss_at(-2.718255fx);
        move_rand(1.9fx);
        card_wait(60, 1.9fx);
    }
}

// Source Boss3_at 411-445. The synchronous call keeps the same task and its shooter.
// %F0 is passed by value; %A/RANDRAD, $B and $C become locals with the same counts.
sub boss_at(f0: fx) {
    // Source 423: %A = %RANDRAD (signed -pi..pi). Target full BAM circle.
    var a: int = rand(65536) - 32768;
    // Source 429/439: %A += 0.05235988*%F0 (3 deg) and %A -= 0.017453292*%F0 (1 deg).
    var inc3: int = (((3deg as int) as fx) * f0) as int;
    var inc1: int = (((1deg as int) as fx) * f0) as int;

    // Source 424-433: $B=10 full rounds; each fires then waits 5 frames.
    for i in 0..10 {
        sh_angle(0, (a + H_A) as angle, (0 - DELTA_A) as angle);
        sh_fire(0);
        a = a + inc3;
        wait(5);
    }
    // Source 434-443: $C=10 rounds with the second delta; each fires then waits 5 frames.
    for j in 0..10 {
        sh_angle(0, (a + H_B) as angle, (0 - DELTA_B) as angle);
        sh_fire(0);
        a = a - inc1;
        wait(5);
    }
}

// --- Source moveRand(60,4,1.9) with moveLimit(0,128,280,64) -----------------
// Documented moveRand formula: one direction draw at call time, speed
// 1.9*(1-k/60) for k=1..60, per-tick position clamp x in [-140,140], y in [96,160].
// Direction inner box is center +/- width/height 1/4: x +/- 70, y 112..144.
// The helper pre-arms the next source movement tick because target phase 5 runs
// after ECL; the next boss_at therefore reads the same per-tick positions.
sub card_arm_next_step(init: fx) {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 {
        speed = init * ((60 - k) as fx) / 60fx;
    }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: int, init: fx) {
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    card_arm_next_step(init);
}

sub card_wait(frames: int, init: fx) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step(init);
    }
}

sub move_rand(init: fx) {
    // Source signed unit random * pi. Integer BAM keeps the branch arithmetic and the
    // native unwrapped central branch; only the final angle is cast.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }       // source normalizes only this outer branch
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;    // source WORD modulo 3, including its bias
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
        // Deliberately not normalized before the source fabs tests.
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon 0.05 rad = 522 BAM.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a, init);
}
